#!/bin/zsh
# Drafts every component with NouGenOpen, two at a time. Log: design/loop/drafts.log
cd "$(dirname "$0")/.."
P=/Users/kushboygroup/The\ Observatory/NouGen/nougenshards/.venv/bin/python
d() { "$P" -I design/draft_component.py "$@" >> design/loop/drafts.log 2>&1; }
d TopBar "Top band, two rows, bg-chrome, border-b, drag region (class drag; interactive children no-drag), left padding 84px for the macOS traffic lights. Row 1 (menu bar): brand (small gold square + 'Nou Scripts', semibold); title h1 (19px, truncate) with meta line under it (v{version} · edited {data.modified} · compared with v{prevVersion}); then right-aligned, flex-none: version segmented control (ToggleGroup type=single, items v1..vN, selectVersion); view segmented control Read / Write / As Broadcast / Teleprompter (Read: setView('read') and leave writing; Write: setWriting(true); As Broadcast: setView('broadcast') and leave writing; Teleprompter: setPrompter(true)); outline buttons: 'Changes · N' (hidden when no prevVersion; toggles showChanges; N = cues changed per data.diff), 'Sources' (toggles showSources, aria-pressed), 'Export .clap' (window.nou.exportClap, shows 'Exported (file)' for 3 s). Row 2 telemetry strip: flat text items separated by hairlines: '1:38 estimated runtime', 'N spoken words', '16s · 4 jobs on camera · OmniAvatar', 'N flagged' in destructive or '0 clichés' — bold value then muted label, tabular-nums. While writing, telemetry reflects the edited text (countWords/lint with data.banlist, data.wordsPerSecond)." &
d IconRail "Vertical 56px rail, bg-rail, border-r, items centred, gap 4, padding-top 12. Four icon buttons (lucide: BookOpen 'Stories', Image 'Media sources', FileText 'Desk', Link2 'Sources'), 38x38, rounded-md, muted; hover bg-card; active = nou.panel===name && !nou.railCollapsed: bg-secondary text-foreground with a 2px gold bar on its left edge. Each has a Tooltip with the label (side right) and a count badge top-right (tabular, 9px; gold bg when active): media = nou.media.length, desk = nou.files.desk.length, sources = nou.files.sources.length; no badge for stories or zero. Click = nou.setPanel(name)." &
wait
d SidePanel "The 248px panel column next to the icon rail; bg-sidebar, border-r, flex column, overflow hidden; render nothing visible when nou.railCollapsed. Header row: uppercase 10px tracked label of the section (Stories / Media sources / Desk / Sources), count for stories, and a ghost icon button (ChevronLeft) that collapses (setRailCollapsed(true)). Sections by nou.panel: STORIES = search input ('Find a story…', Cmd+K focuses it), filter ToggleGroup All / Approved / Needs review (approved = s.approval && s.approvalCurrent), list of story buttons (letter avatar, title truncate, sub row: id first 10 chars, v{latest}, status text gold 'needs review' / green 'v{n} approved' / gold 'approval stale'), active story has gold-soft bg and gold border; footer shows nou.root truncated. MEDIA = filter (All/Photos/Video/Audio with counts, only kinds present) and a 2-column grid of tiles from nou.media: face = photo (img src fileUrl(m.path)) or, for a video, its thumbnail (the image item with same source and via==='thumbnail') with a small play badge, else a glyph; caption = label truncate, 'kind · host'; small outline actions: Digest (non-images: nou.requestDigest(m.url)), Attach (when m.path: nou.addChips([await window.nou.mediaAttach(id,url)]), Copy as 'VIDEO line' to clipboard ('VIDEO: Photo|Clip|Audio: label (url)') and report via nou.setReply. Empty text: 'Digest or fetch a link and its photos, videos and audio appear here.' DESK = nou.files.desk rows (kind tag research=gold / digest=violet, title 2-line clamp, eastern(mtime)); click window.nou.open(path). Empty: 'Research briefs and digests you run from the producer line land here.' SOURCES = nou.files.sources rows (kind tag, title, host(url) or name); click open. Empty: 'Pages, transcripts and PDFs read for this story are saved here.'" &
d RightRail "320px right rail, bg-[#141415], border-l, overflow-auto, padding 16, padding-bottom 40. Approval block (no box unless state): states exactly as REFERENCE renderApproval (approved = green tint box; stale = gold tint box; else plain): heading 14px semibold, muted 12px reason, and a full-width default (gold) Button 'Approve v{version}' when approvable. The button opens a shadcn Dialog: title 'Approve v{version} for render', description '{title} · {fmtTime(seconds)} · {avatarJobs} OmniAvatar jobs. This records the exact file contents; any later edit needs a new approval.', a Textarea labelled 'Note for the render step (optional)' placeholder 'e.g. keep line 5 slow', Cancel (ghost) and Approve (default) -> await nou.approve(note). Hide the approval block while nou.writing. Below: notes from data.script.notes: each section h3 (14px), list items muted 13px with Inline markdown, 16px indent, 6px item gap; non-list lines as paragraphs." &
wait
d ScriptView "The main column content (max width 960). Version banner (gold soft box, 12px) exactly as REFERENCE load() banner logic. If nou.writing: a sticky write bar (card, gold-ish border): status text exactly as REFERENCE updateWriteState (empty-line warning, 'N lines edited · W words · ~T. vX stays as it is.', or 'Editing vX. Saving makes vY; vX stays as it is.'), 'Discard' ghost (nou.setWriting(false)) and outline 'Save as vY' (disabled when nothing changed or a line is empty; Cmd/Ctrl+S saves) -> await nou.save(). Cue list: each cue a card (bg #161618, rounded-lg, no outline until hover, 3px left bar gold for on-camera, violet for VO): head row = number, kind tag (ON CAM gold / VO violet, uppercase 10px), hint muted, 'changed'/'new' tag when data.prevVersion and data.diff[i] !== 'same', cliché tag in destructive, right side mono '{words} words · ~{seconds}s'. Body: when writing, an auto-growing Textarea in font-read 18px with live count/lint per cue and an 'edited' gold border; otherwise font-read 18px text with word changes from data.changes[i] shown as <ins>/<del> runs when nou.showChanges (else plain). Source line (when nou.showSources and c.source) under a dashed hairline, muted 12px with Inline. If nou.view==='broadcast' and not writing: render the As Broadcast table exactly as REFERENCE asBroadcast(): header strip (Program, Slug, Talent, Version, TRT) then table Time code (mono, with seconds under) · Segment · Video (VIDEO lines, GFX, SUPER split on ' | ', or 'Nou on camera' / italic 'Pictures to come') · Audio (MUSIC/SFX/NAT directions, spoken copy font-read 16px, SOT lines, source) and a footer row with total running time. Empty state when !nou.data: 'Put a script_v1.md in a story folder under {root}.'" &
d Dock "Bottom band: grid 304px | 1fr | 320px, gap 12, padding 10/14/12, bg-chrome, border-t. LEFT module (card, rounded-lg, padding 10/12): label 'PRODUCER LINE' (10px tracked faint), a segmented ToggleGroup of lanes Edit / Web fetch / Research, a Select of models ('nvidia/nemotron-3-ultra-550b-a55b' = 'Nemotron 3 Ultra · NVIDIA', 'mistralai/mistral-large-4-1t-a52b' = 'Mistral Large 4 · NVIDIA'), and the lane note (exact texts from REFERENCE LANES). CENTRE module (card, border neutral, gold border on focus-within, content vertically centred): chips row from nou.chips (name truncate max 260px, x removes via nou.removeChip), then a row: '+' outline icon button (window.nou.attach() -> nou.addChips), auto-growing Textarea (rows 1, max 140px, 15px font-read, placeholder per lane from REFERENCE LANES; Enter submits, Shift+Enter newline), an outline 'Digest' button (requires a URL in the box; else setReply('Paste a link in the box first: a page, PDF, YouTube, audio or video.', 'err')) and an outline icon Send button (ArrowUp). Submit routes by lane exactly as REFERENCE: edit -> window.nou.ask({id,version,cues: nou.scriptCues(),instruction,attachmentIds: chip ids,model}) then, when edits came back, nou.setWriting(true, {...current edits if writing, ...r.edits}); fetch -> fetchPages; research -> research; digest -> digest; same reply texts as REFERENCE (via nou.setReply(text, tone, file)); add returned chips; call nou.refreshAux() after fetch/digest/research. Also react to nou.pendingDigest: when it changes, put its url in the box and run digest, then nou.setPendingDigest(null). Disable buttons while busy. RIGHT module: label 'LAST REPLY', nou.reply.text (12px muted, scroll, gold when tone busy, destructive when err) and an 'Open' small outline button when nou.reply.file (window.nou.open)." &
wait
d Teleprompter "Full-screen fixed overlay (z-50, bg black). Top bar: '{title} · v{version}', help 'Space play/pause · ↑↓ speed · Esc exit', buttons Mirror (toggles scaleX(-1) on the text), A- / A+ (font size 24..80, start 46), and the speed readout '{speed} px/s · playing'. Scroll area with each cue as a block: small label '{n} · ON CAM|kind' (gold/violet) then the text in font-read at the font size, centred column max 900px; a faint horizontal reading line at 35% height. requestAnimationFrame auto-scroll at speed px/s (start 40, ↑/↓ by 5 between 5 and 200), Space toggles, Esc closes (nou.setPrompter(false)). Clean up listeners and rAF on unmount."
echo done >> design/loop/drafts.log
